{
  "summary": "Refactor metrics to live in session.state.runtime instead of world.snapshot. Updated RuntimeState type to include metrics, modified buildMessages to attach metrics to runtime, and updated reduceClientState to read metrics from session.state.runtime.",
  "files": [
    {
      "path": "packages/protocol/src/messages.ts",
      "content": "export type RuntimeState = {
  model: string | null;
  tickMs: number;
  metrics: {
    turnsTotal: number;
    invalidOutputCount: number;
    actionAppliedCount: number;
    actionRejectedCount: number;
    queuedActions: number;
  };
};

export type SessionStateMessage = {
  type: "session.state";
  payload: {
    phase: "idle" | "running" | "paused";
    runtime: RuntimeState;
  };
};

export type WorldSnapshotMessage = {
  type: "world.snapshot";
  payload: {
    tick: number;
    world: Record<string, unknown>;
  };
};"
    },
    {
      "path": "apps/game-runtime/src/runtime/sessionState.ts",
      "content": "import type { SessionStateMessage, WorldSnapshotMessage } from "@codexgame/protocol";
import type { RuntimeMetrics } from "./metrics";

export function buildMessages(metrics: RuntimeMetrics): {
  sessionState: SessionStateMessage;
  worldSnapshot: WorldSnapshotMessage;
} {
  return {
    sessionState: {
      type: "session.state",
      payload: {
        phase: "running",
        runtime: {
          model: "local-qwen",
          tickMs: 200,
          metrics,
        },
      },
    },
    worldSnapshot: {
      type: "world.snapshot",
      payload: {
        tick: 42,
        world: {},
      },
    } as unknown as WorldSnapshotMessage,
  };
}"
    },
    {
      "path": "apps/game-client/src/state.ts",
      "content": "export type ClientState = {
  phase?: string;
  runtime?: Record<string, unknown>;
  world?: Record<string, unknown>;
};

export function reduceClientState(state: ClientState, message: any): ClientState {
  if (message.type === "session.state") {
    return {
      ...state,
      phase: message.payload.phase,
      runtime: message.payload.runtime,
    };
  }
  if (message.type === "world.snapshot") {
    return {
      ...state,
      world: message.payload.world,
    };
  }
  return state;
}"
    }
  ]
}
